//! A web framework on top of [`axum`] with first-class OpenAPI documentation support.
//!
//! Endpoints are declared with [`Endpoint`], validated against the JSON schemas of their
//! types (generated by [`schemars`]), registered with [`create_api`] and documented with
//! [`build_json`].

pub mod adapter;
pub mod core;
pub mod err;
pub mod grouping;
pub(crate) mod internal;
pub mod json_builder;
pub mod security;

